import { createHash } from 'node:crypto';
import { caseClassification } from './benchmark.js';
import { isAlert, type CaseResult, type Confusion, type SecurityBenchmark, type SecurityReview } from './types.js';

const escape = (input: unknown) => String(input).replace(/[&<>"']/g, character => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[character]!));
const percent = (value: number | null) => value === null ? 'N/A' : `${(value * 100).toFixed(1)}%`;
const link = (url: string, label: string) => { try { return new URL(url).protocol === 'https:' ? `<a href="${escape(url)}" rel="noreferrer">${escape(label)}</a>` : escape(label); } catch { return escape(label); } };
const css = `:root{color-scheme:light;font-family:system-ui,sans-serif;color:#172c31;background:#f4f6f5}*{box-sizing:border-box}body{margin:0}main{max-width:1180px;margin:auto;padding:32px 22px}h1{font-size:clamp(28px,4vw,42px);line-height:1.1;margin:12px 0}h2{margin-top:32px;font-size:23px}h3{font-size:17px;margin-bottom:8px}p,li{line-height:1.55}a{color:#16574c}small,.muted{color:#4b6268}code,pre{font-family:ui-monospace,monospace;font-size:13px}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f1f4f2;padding:12px;border-radius:6px}code,p,td,li,summary{overflow-wrap:anywhere}section,article,.card{border:1px solid #cdd9d5;border-radius:12px;background:white;padding:20px;margin:16px 0}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:12px}.card{margin:0}.number{font-size:28px;font-weight:750;display:block}.tag{display:inline-block;font-size:12px;border-radius:4px;background:#e8efec;padding:3px 8px;margin-right:8px;font-weight:650}.TP,.risk_detected{background:#fbe6d7}.FN,.FP,.ERROR,.unverified,.INCOMPLETE{background:#ffe2e2}.TN,.no_alert{background:#e1f0e9}summary{cursor:pointer;line-height:1.6;font-weight:650}details{border-top:1px solid #dce4e0;margin-top:12px;padding-top:12px}details details{background:#f9faf9;padding:12px;border:1px solid #dce4e0;border-radius:6px}.scroll{overflow:auto}table{border-collapse:collapse;width:100%;font-size:14px}th,td{text-align:left;border-bottom:1px solid #dae2df;padding:10px;vertical-align:top}th{background:#edf3ef}.controls{display:flex;flex-wrap:wrap;gap:12px;align-items:end;position:sticky;top:0;background:#f4f6f5;padding:12px 0;z-index:1}label{font-size:13px;font-weight:650;display:flex;flex-direction:column;gap:6px}input,select{font:inherit;padding:9px;border:1px solid #8ea59b;border-radius:6px;max-width:100%;background:white}input{min-width:220px}a:focus-visible,summary:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #b67b13;outline-offset:2px}.origin{border-left:3px solid #aabbb4;padding-left:12px}.warning{border-left:4px solid #be6b24;padding:10px 14px;background:#fff6eb}footer{padding:24px 0;color:#4b6268;font-size:13px}[hidden]{display:none!important}@media(max-width:600px){main{padding:20px 12px}section,article{padding:14px}.controls{position:static}th,td{padding:8px;min-width:85px}}@media print{.controls{display:none}body{background:white}main{max-width:none;padding:0}details{break-inside:avoid}}`;
const filterScript = `const search=document.getElementById('search');const filter=document.getElementById('filter');const cases=[...document.querySelectorAll('[data-case]')];function update(){let visible=0;for(const item of cases){const match=item.textContent.toLowerCase().includes(search.value.toLowerCase())&&(filter.value==='all'||item.dataset.classification===filter.value);item.hidden=!match;if(match)visible++;}document.getElementById('visible').textContent=visible+' of '+cases.length+' cases shown';}search.addEventListener('input',update);filter.addEventListener('change',update);update();`;
function shell(title: string, content: string, interactive = false): string {
  const hash = createHash('sha256').update(filterScript).digest('base64');
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; script-src ${interactive ? `'sha256-${hash}'` : "'none'"}; base-uri 'none'; form-action 'none'"><title>${escape(title)}</title><style>${css}</style></head><body><main>${content}<footer>HoneySkill Security v1 · local research evidence · no safety certification</footer></main>${interactive ? `<script>${filterScript}</script>` : ''}</body></html>`;
}
function metricsTable(rows: [string, Confusion][]): string {
  return `<div class="scroll"><table><thead><tr><th>Method / population</th><th>Total</th><th>TP</th><th>FN</th><th>FP</th><th>TN</th><th>Excluded</th><th>Unlabelled completed</th><th>Conditional recall</th><th>FPR</th><th>Labelled coverage</th><th>Positive coverage</th><th>Detection floor</th></tr></thead><tbody>${rows.map(([name, m]) => `<tr><td>${escape(name)}</td><td>${m.attempted}</td><td>${m.tp}</td><td>${m.fn}</td><td>${m.fp}</td><td>${m.tn}</td><td>${m.incomplete}</td><td>${m.unknown}</td><td>${percent(m.recall)}</td><td>${percent(m.falsePositiveRate)}</td><td>${m.coverage.labelled}/${m.labels.malicious + m.labels.benign} (${percent(m.coverage.labelledRate)})</td><td>${m.coverage.malicious}/${m.labels.malicious} (${percent(m.coverage.maliciousRate)})</td><td>${percent(m.endToEndDetectionFloor)}</td></tr>`).join('')}</tbody></table></div>`;
}
function abstentionsTable(rows: [string, Confusion][]): string {
  const keys = ['error', 'unsupported', 'partial', 'notRequested', 'missingEngine', 'partialPackage', 'coverageGap'] as const;
  return `<div class="scroll"><table><thead><tr><th>Method</th><th>Error</th><th>Unsupported</th><th>Partial analysis</th><th>Not requested</th><th>Missing engine</th><th>Partial package</th><th>Coverage gap</th></tr></thead><tbody>${rows.map(([name, m]) => `<tr><td>${escape(name)}</td>${keys.map(key => `<td>${m.abstentions[key]}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
}
function reviewDetails(review: SecurityReview): string {
  return `<p><span class="tag ${review.outcome}">${escape(review.outcome.replaceAll('_',' '))}</span> Selected inspection: <strong>${review.inspectionComplete ? 'complete' : 'incomplete'}</strong> · ${(review.durationMs / 1000).toFixed(1)} s · ${review.coverage.readableFiles}/${review.coverage.files} readable files</p>
  <div class="scroll"><table><thead><tr><th>Check</th><th>Result</th><th>Alerts</th><th>Time</th><th>What this proves</th></tr></thead><tbody>${review.engines.map(stage => `<tr><td>${escape(stage.engine)}<br><small>${escape(stage.version)}</small></td><td>${escape(stage.status)}</td><td>${stage.findings.filter(isAlert).length}</td><td>${(stage.durationMs/1000).toFixed(2)} s</td><td>${stage.kind === 'static' ? 'Content / code inspection; no execution' : 'Model interpretation with validated source citations'}${stage.responseId ? `<br><code>${escape(stage.responseId)}</code>` : ''}</td></tr>`).join('')}</tbody></table></div>
  ${review.coverage.gaps.length ? `<h3>Missing coverage</h3><ul>${review.coverage.gaps.map(gap => `<li>${escape(gap)}</li>`).join('')}</ul>` : ''}
  ${review.engines.filter(stage=>stage.requests).map(stage=>`<details><summary>Semantic request ledger · ${stage.batching?.completed}/${stage.batching?.planned} batches complete · ${escape(stage.transport)}</summary><p>Every readable source fragment is assigned to one batch. Cross-batch interactions may be missed. ${stage.usage?.totalTokens??0} recorded tokens.</p><div class="scroll"><table><thead><tr><th>Batch</th><th>Status</th><th>Source fragments</th><th>Response</th><th>Tokens</th></tr></thead><tbody>${stage.requests!.map(request=>`<tr><td>${request.batch}</td><td>${escape(request.status)}</td><td>${request.sourceIds.length}</td><td><code>${escape(request.responseId??'No response recorded')}</code></td><td>${request.usage?.totalTokens??'N/A'}</td></tr>`).join('')}</tbody></table></div></details>`).join('')}
  ${review.engines.map(stage => `${stage.errors.length ? `<h3>${escape(stage.engine)}: what did not finish</h3><ul>${stage.errors.map(error => `<li>${escape(error)}</li>`).join('')}</ul>` : ''}${stage.findings.length ? `<details><summary>${escape(stage.engine)} evidence · ${stage.findings.length} findings</summary>${stage.findings.map(finding => `<details><summary><span class="tag">${escape(finding.severity)}</span>${escape(finding.title)} <small>(${escape(finding.rule)})</small></summary><p>${escape(finding.explanation)}</p>${finding.evidence.map(evidence => `<div class="origin"><p><code>${escape(evidence.file)}${evidence.line ? `:${evidence.line}` : ''}</code> · ${evidence.verified ? evidence.redacted ? 'source quotation verified before redaction' : 'source location verified' : 'source location not verified'}</p>${evidence.excerpt ? `<pre>${escape(evidence.excerpt)}</pre>` : ''}</div>`).join('')}</details>`).join('')}</details>` : ''}`).join('')}
  <details><summary>Snapshot identity and limits</summary><p>SHA-256 <code>${escape(review.fingerprint)}</code></p><p>Runtime: ${escape(review.coverage.execution)}. Capability compatibility: ${escape(review.coverage.runtimeSupport)}.</p><ul>${review.limitations.map(item => `<li>${escape(item)}</li>`).join('')}</ul></details>`;
}
export function securityReviewHtml(review: SecurityReview): string {
  return shell(`HoneySkill · ${review.name}`, `<p class="muted">SECURITY INSPECTION</p><h1>${escape(review.name)}</h1><p class="warning">No alert does not mean safe. This report inspects files; it does not execute or install the skill.</p><section>${reviewDetails(review)}</section>`);
}
function caseCard(item: CaseResult): string {
  const classification = caseClassification(item);
  const alerts = item.review?.engines.reduce((sum, stage) => sum + stage.findings.filter(isAlert).length, 0) ?? 0;
  return `<article id="case-${escape(item.sample.id)}" data-case data-classification="${classification}"><details><summary><span class="tag ${classification}">${classification}</span>${escape(item.sample.name)} <small>· ${alerts} alerts · ${escape(item.sample.id)}</small></summary>
    <p><strong>Ground truth:</strong> ${escape(item.sample.groundTruth.label)} · ${escape(item.sample.provenanceKind)}<br>${escape(item.sample.groundTruth.basis)}</p>
    <p><strong>Documented threats:</strong> ${escape(item.sample.documentedThreatTypes.join(', ') || 'No independent threat label')}<br><strong>Family/source group:</strong> ${escape(item.sample.family)}<br><strong>Package:</strong> ${escape(item.sample.packageCompleteness.status)}</p>
    <p>${link(item.sample.documentationUrl, 'Incident / research source')} · ${link(item.sample.sourceUrl, 'Pinned sample source')}</p>
    ${classification === 'FN' ? '<p class="warning">The source labels this package malicious. The completed selected checks produced no MEDIUM+ alert. This is a missed detection.</p>' : ''}
    ${classification === 'UNLABELLED' ? '<p class="warning">No independent benign/malicious label: this result does not enter TP/FP/TN/FN.</p>' : ''}
    ${item.error ? `<p class="warning">Inspection did not complete: ${escape(item.error)}</p>` : item.review ? reviewDetails(item.review) : '<p>No report.</p>'}
    </details></article>`;
}
export function securityBenchmarkHtml(result: SecurityBenchmark): string {
  const m = result.metrics.combined!, classes = result.cases.map(caseClassification);
  const rows = Object.entries(result.metrics), methods = rows.filter(([name]) => !name.startsWith('family:') && !name.startsWith('source:'));
  const families = rows.filter(([name]) => name.startsWith('family:')), sources = rows.filter(([name]) => name.startsWith('source:'));
  return shell('HoneySkill · Security benchmark', `<p class="muted">DEVELOPMENT EVALUATION · ${escape(result.startedAt)}</p><h1>What did HoneySkill catch?</h1><p>Real source snapshots, explicit ground truth, and a traceable reason for every result.</p>
  <div class="cards">${[[result.cases.length,'attempted packages'],[m.tp,'detected positives'],[m.fn,'missed positives'],...(m.labels.benign ? [[m.fp,'benign cases flagged'],[m.tn,'benign cases without alert']] : []),[m.incomplete,'incomplete / excluded'],[m.unknown,'unlabelled controls']].map(([value,label]) => `<div class="card"><span class="number">${value}</span>${label}</div>`).join('')}</div>
  <p class="warning"><strong>Scope:</strong> package inspection, not malware execution or runtime prevention. Partial snapshots and incomplete checks are excluded from accuracy metrics and remain visible. A selected public corpus is not an unseen blind test.</p>
  <section><h2>Results by method</h2><p>Threshold fixed before the run: MEDIUM+. A positive is an alert, not a successful exploit. Missing denominators are N/A.</p>${metricsTable(methods)}
  <p><strong>Conditional recall</strong> = TP / completed labelled malicious cases. <strong>Positive coverage</strong> = completed labelled malicious / all labelled malicious. <strong>Detection floor</strong> = TP / all labelled malicious, including excluded positives in the denominator; exclusions remain abstentions, not false negatives. No method requested means N/A.</p>
  <p>Labels before exclusions: ${m.labels.malicious} malicious, ${m.labels.benign} benign, ${m.labels.unknown} unknown or not independently labelled. Without independently labelled benign cases, FP/TN/FPR and general accuracy cannot be established.</p>
  <h3>Why cases were excluded</h3>${abstentionsTable(methods)}<p>Each excluded case has one primary reason, in this order: missing review, missing engine, engine error, unsupported engine, partial analysis, not requested, partial package, coverage gap. Detailed cases retain every reported issue.</p>
  <p>Elapsed ${(result.durationMs/1000).toFixed(1)} s · semantic review ${result.configuration.semantic ? 'requested' : 'not requested'} · no silent retries.</p><p><strong>TP</strong> source-labelled attack flagged · <strong>FN</strong> source-labelled attack missed · <strong>FP</strong> independently labelled benign case flagged · <strong>TN</strong> independently labelled benign case without alert.</p></section>
  <section><h2>Grouped results</h2><p>Groups describe this selected corpus; their rows are correlated and are not independent attack campaigns. No independent-sample confidence interval is inferred.</p><details><summary>${families.length} family / source groups</summary>${metricsTable(families)}</details><details><summary>${sources.length} documentation sources</summary>${metricsTable(sources)}</details></section>
  <h2>Review the cases</h2><p>Open a case to see what worked, what did not, and the exact file passage behind each alert.</p>
  <div class="controls"><label>Search name, threat, rule or source<input id="search" type="search" placeholder="private key, swap, exfiltration…"></label><label>Result<select id="filter"><option value="all">All cases</option>${[...new Set(classes)].sort().map(value => `<option>${value}</option>`).join('')}</select></label><span id="visible" class="muted"></span></div>
  ${result.cases.map(caseCard).join('')}
  <section><h2>How to check this evidence</h2><p>The companion JSON retains the input hashes, source labels, per-engine results and source freeze. The verifier checks schema, derived outcomes, corpus-to-snapshot file identities, counts and recorded source digests without a model. It checks internal consistency; it cannot authenticate upstream execution, the original corpus, or source labels.</p><p>Corpus SHA-256 <code>${escape(result.corpusSha256)}</code><br>Code freeze SHA-256 <code>${escape(result.freeze.sha256)}</code></p><ul>${result.limitations.map(item => `<li>${escape(item)}</li>`).join('')}</ul></section>`, true);
}
export function securityBenchmarkMarkdown(result: SecurityBenchmark): string {
  const metric = result.metrics.combined!;
  const md = (value: string) => value.replace(/[\x00-\x1f\x7f]/g, ' ').replace(/([\\`*_{}\[\]()#+\-.!|<>])/g, '\\$1');
  return `# HoneySkill security evaluation\n\n${md(result.startedAt)}. Development external corpus; static package inspection, not a blind holdout or malware execution.\n\n- Attempted: ${result.cases.length}\n- TP ${metric.tp}; FN ${metric.fn}; FP ${metric.fp}; TN ${metric.tn}\n- Incomplete/excluded: ${metric.incomplete}; completed unlabelled: ${metric.unknown}\n- All labels: ${metric.labels.malicious} malicious; ${metric.labels.benign} benign; ${metric.labels.unknown} unknown\n- Conditional recall: ${percent(metric.recall)}; FPR: ${percent(metric.falsePositiveRate)}\n- Labelled coverage: ${metric.coverage.labelled}/${metric.labels.malicious + metric.labels.benign} (${percent(metric.coverage.labelledRate)})\n- Positive coverage: ${metric.coverage.malicious}/${metric.labels.malicious} (${percent(metric.coverage.maliciousRate)})\n- Detection floor (TP / all labelled positives): ${percent(metric.endToEndDetectionFloor)}; excluded cases remain abstentions\n- Exclusions: ${Object.entries(metric.abstentions).map(([key,value]) => `${key}=${value}`).join('; ')}\n\n## Case index\n\n| Case | Ground truth | Result | Package |\n| --- | --- | --- | --- |\n${result.cases.map(item => `| ${md(item.sample.id)} — ${md(item.sample.name)} | ${item.sample.groundTruth.label} | ${caseClassification(item)} | ${item.sample.packageCompleteness.status} |`).join('\n')}\n\n## Family / source groups\n\nThese are correlated groups, not independent campaigns. Full grouped matrices are retained in JSON and HTML.\n\n| Group | Attempted | TP | FN | FP | TN | Excluded |\n| --- | --- | --- | --- | --- | --- | --- |\n${Object.entries(result.metrics).filter(([key]) => key.startsWith('family:')).map(([key,m]) => `| ${md(key.slice(7))} | ${m.attempted} | ${m.tp} | ${m.fn} | ${m.fp} | ${m.tn} | ${m.incomplete} |`).join('\n')}\n\n## Limits\n\n${result.limitations.map(item => `- ${md(item)}`).join('\n')}\n`;
}
